<section class="card" id="clients"><h2>用户接入</h2><p>授权码 + PKCE S256。保存应用会撤销其旧凭证，每行一个完整回调地址。</p><?php $clients[]=['id'=>'','name'=>'','redirect_uris'=>'[]','logout_uris'=>'[]','confidential'=>1,'enabled'=>1];foreach($clients as $c): ?><details><summary><?= $e($c['id']?$c['name'].' · '.$c['id']:'＋ 新建应用') ?></summary><form method="post" action="/admin/client"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><label>应用 ID<input name="id" value="<?= $e($c['id']) ?>" <?= $c['id']?'readonly':'' ?> required></label><label>名称<input name="name" value="<?= $e($c['name']) ?>" required></label><label>登录回调<textarea name="redirect_uris" required><?= $e(implode("\n",json_decode($c['redirect_uris'],true))) ?></textarea></label><label>退出回调<textarea name="logout_uris"><?= $e(implode("\n",json_decode($c['logout_uris'],true))) ?></textarea></label><label>类型<select name="confidential"><option value="1" <?= $c['confidential']?'selected':'' ?>>服务端应用（密钥）</option><option value="0" <?= !$c['confidential']?'selected':'' ?>>公共客户端（无密钥）</option></select></label><label class="check"><input type="checkbox" name="enabled" value="1" <?= $c['enabled']?'checked':'' ?>>启用</label><label class="check"><input type="checkbox" name="rotate" value="1">重新生成密钥</label><button>保存应用</button></form></details><?php endforeach ?></section>
